    'blog.art.cta.gbp.btn': 'Ver nuestro servicio de SEO local',
    'a.bo.0': '¿Cuándo vale la pena crear una tienda online para tu negocio?',
    'a.bo.1': 'Muchos propietarios de tiendas y comercios locales nos preguntan si deberían tener tienda online. La respuesta honesta es: depende. Una tienda online puede ser lo mejor que hagas para tus ingresos, o una inversión importante que no da retorno. Aquí te ayudamos a decidir.',
    'a.bo.10': 'Una tienda online es especialmente útil cuando tienes muchos productos y los clientes necesitan ver todo el catálogo para decidir. Si tienes 5 productos muy sencillos, quizás un formulario de contacto o de pedido básico es suficiente sin la complejidad de una tienda online completa.',
    'a.bo.11': 'Cuándo NO tiene sentido (o no es el momento)',
    'a.bo.12': 'Vendes servicios, no productos',
    'a.bo.13': 'Si eres asesor, médico, abogado, diseñador, consultor o cualquier profesional de servicios, no necesitas una tienda online — necesitas una web de presentación bien hecha con formulario de contacto. La venta de servicios requiere conversación previa, no un carrito de la compra.',
    'a.bo.14': 'No tienes tiempo de gestionarla',
    'a.bo.15': 'Una tienda online no funciona sola. Necesitas añadir y actualizar productos, gestionar stock, responder consultas de clientes, preparar y enviar pedidos, gestionar devoluciones... Si no puedes dedicar entre 5 y 10 horas semanales a la tienda, mejor esperar hasta que puedas hacerlo bien.',
    'a.bo.16': 'Acabas de empezar y no sabes si el producto se venderá',
    'a.bo.17': 'Hacer una tienda online antes de validar que el producto tiene demanda es arriesgado. Mejor vender primero por los canales más sencillos (Instagram, Wallapop, Etsy, mercado local) para confirmar que hay interés, y entonces invertir en una tienda profesional.',
    'a.bo.18': 'Cuánto cuesta realmente una tienda online',
    'a.bo.19': 'El coste de una tienda online va mucho más allá del precio de desarrollo. Aquí tienes el desglose real:',
    'a.bo.2': 'Cuándo SÍ tiene sentido crear una tienda online',
    'a.bo.20': '<strong>Desarrollo:</strong> 800€ - 3.000€ para una tienda profesional',
    'a.bo.21': '<strong>Hosting adecuado:</strong> 15€ - 50€/mes (las tiendas necesitan servidores mejores que las webs de presentación)',
    'a.bo.22': '<strong>Pasarela de pago:</strong> Stripe cobra un 1,4% + 0,25€ por transacción (para tarjetas europeas). En 100 pedidos de 50€ cada uno, son unos 95€ de comisiones',
    'a.bo.23': '<strong>Embalaje y mensajería:</strong> variable, pero un envío estándar ronda los 3€ - 8€ que quizás tienes que absorber tú o trasladar al cliente',
    'a.bo.24': '<strong>Mantenimiento y actualizaciones:</strong> 30€ - 80€/mes si lo delegas',
    'a.bo.25': '<strong>Marketing:</strong> sin publicidad ni SEO, una tienda nueva recibirá muy poco tráfico los primeros meses',
    'a.bo.26': 'Haz los números antes de empezar: ¿cuántas ventas necesitas al mes para recuperar la inversión y pagar los costes recurrentes?',
    'a.bo.27': 'Alternativas a la tienda online propia',
    'a.bo.28': 'Si no es el momento para una tienda propia, hay alternativas que te permiten vender online con menos inversión inicial:',
    'a.bo.29': '<strong>Marketplaces (Amazon, Etsy, Wallapop):</strong> pagas comisión pero tienes tráfico inmediato. Bien para validar el producto',
    'a.bo.3': 'Tienes productos físicos con margen suficiente',
    'a.bo.30': '<strong>Instagram Shopping:</strong> para productos visuales con una comunidad activa ya construida',
    'a.bo.31': '<strong>WhatsApp Business:</strong> para ventas directas y clientela local, WhatsApp es sorprendentemente eficaz',
    'a.bo.32': 'Cuando hayas validado el producto y la demanda, es el momento de hacer la inversión en una tienda online propia bien hecha.',
    'a.bo.33': 'Los factores de éxito de una tienda online',
    'a.bo.34': 'Las tiendas online que funcionan suelen tener en común:',
    'a.bo.35': 'Un producto con demanda real y margen suficiente',
    'a.bo.36': 'Fotos de producto de calidad (la principal razón por la que se compra o no se compra)',
    'a.bo.37': 'Descripciones de producto claras y detalladas',
    'a.bo.38': 'Proceso de compra simple (demasiados pasos = abandono del carrito)',
    'a.bo.39': 'Política de devoluciones clara y sin trampas',
    'a.bo.4': 'Una tienda online añade costes: la plataforma, el tiempo de añadir productos, el servicio de mensajería, los embalajes, las devoluciones. Si tu margen por producto es pequeño, los costes del ecommerce pueden comerse los beneficios. Como referencia, un margen neto de al menos el 30-40% hace que la tienda online sea viable.',
    'a.bo.40': 'SEO de producto: que los productos aparezcan en Google cuando alguien los busca',
    'a.bo.41': 'Reseñas de clientes reales',
    'a.bo.5': 'Tu producto se puede enviar fácilmente',
    'a.bo.6': 'Los productos pequeños, ligeros y que aguantan bien el transporte son los ideales para ecommerce. Los productos frágiles, muy pesados, perecederos (comida fresca) o que necesitan instalación complicada representan un reto logístico importante que puede hacer que la tienda online no sea viable sin una operativa bien pensada.',
    'a.bo.7': 'La gente busca tu producto por internet',
    'a.bo.8': 'Hay productos que la gente compra mayoritariamente online (ropa, electrónica, complementos, productos de nicho) y productos que preferentemente se compran en el local (comida fresca, servicios). Si tu producto tiene volumen de búsqueda en internet, la tienda online tiene mucho más sentido.',
    'a.bo.9': 'Tienes un catálogo amplio y claro',
    'a.cl.0': 'Diseño web para clínicas y profesionales de la salud',
    'a.cl.1': 'Para quién es este artículo',
