    'a.cl.11': 'Preguntas frecuentes',
    'a.cl.12': 'Puedo publicar resenas de pacientes en la web de mi clínica?',
    'a.cl.13': '¿La web debe estar en catalán, castellano o los dos?',
    'a.cl.14': '¿Cuánto tarda en estar lista la web?',
    'a.cl.2': 'Para qué sirve una web para una clínica',
