    'a.cl.8': 'Aviso legal y política de privacidad (LOPD)',
    'a.cl.9': 'SEO local para clínicas: cómo aparecer en Google',
    'a.ft.0': 'Qué fotos necesita la web de tu negocio (y cómo hacerlas con el móvil)',
    'a.ft.1': 'Para qué sirven las fotos en la web (más de lo que crees)',
    'a.ft.10': 'Clínicas y profesionales de la salud',
    'a.ft.11': 'Tiendas y comercios',
    'a.ft.12': 'Cómo hacer buenas fotos con el móvil (sin ser fotógrafo)',
    'a.ft.13': 'La clave de las buenas fotos con móvil no es la cámara — es la luz. Aquí tienes los consejos básicos:',
    'a.ft.14': 'Optimizar las fotos para la web',
    'a.ft.15': 'Preguntas frecuentes',
    'a.ft.16': 'Puedo usar fotos de bancos de imágenes (Unsplash, Pexels) para mi web?',
    'a.ft.2': 'Las fotos imprescindibles para cualquier negocio',
