    'bi.ve.t': 'Web para veterinarios y clínicas veterinarias',
    'bi.ve.d': 'Cómo debe ser la web de una clínica veterinaria para generar confianza antes de la primera visita: cita online, equipo, urgencias y SEO local.',
    'bi.dt.t': 'Web para dentistas y clínicas dentales',
    'bi.dt.d': 'Cómo debe ser la web de una clínica dental para generar confianza y llenar la agenda: tratamientos claros, equipo, antes/después y cita online.',
    'bi.tm.t': 'Web para talleres mecánicos',
    'bi.tm.d': 'Cómo debe ser la web de un taller mecánico para recibir más citas de revisión y reparación: servicios claros, presupuesto orientativo y cita online.',
    'bi.gn.t': 'Web para gimnasios y centros deportivos',
    'bi.gn.d': 'Cómo debe ser la web de un gimnasio o centro deportivo para conseguir más altas: horarios, clases dirigidas, entrenadores y alta online.',
    'bi.bl.t': 'Web bilingüe catalán y castellano: por qué importa',
    'bi.bl.d': 'Por qué una web bilingüe catalán/castellano llega a más clientes en Catalunya, cómo hacerlo bien para SEO y los errores más habituales al traducir una web.',
    'bi.ga.t': 'Google Ads o SEO: dónde invertir',
    'bi.ga.d': 'Google Ads o SEO: dónde debe ir el dinero de un negocio local con presupuesto limitado. Diferencias, tiempos de resultado y cómo combinarlos bien.',
    'bi.an.t': 'Cómo saber si tu web funciona: Analytics y GTM',
    'bi.an.d': 'Cómo saber si tu web funciona sin complicarte con estadísticas: qué mirar en Analytics y Google Tag Manager, y qué ignorar.',
