    'blog.tag': 'Blog',
    'blog.hero.title': 'Consells de web, SEO i màrqueting digital per a pimes',
    'blog.hero.desc': 'Articles pràctics per ajudar-te a entendre quan necessites una web, quant hauria de costar, com posicionar-te a Google i com treure el màxim del teu pressupost digital.',
    'blog.cta.proj': 'Tens un projecte web en ment?',
    'blog.cta.btn': 'Demana pressupost gratis',
    'blog.read': "Llegir l'article →",
    'blog.art.cta.seo': 'Vols una web que posicioni a Google des del primer dia?',
    'blog.art.cta.seo.btn': 'Veure el nostre servei de SEO',
    'blog.art.cta.web': 'Vols una web professional pensada per al teu negoci?',
