    'blog.art.cta.rest': 'Vols una web per al teu restaurant que realment porti clients?',
    'blog.art.cta.rest.btn': 'Veure webs per a restaurants',
    'blog.art.cta.shop': 'Estàs pensant en obrir una botiga online?',
