    'a.bo.0': 'When is it worth creating an online store for your business?',
    'a.bo.1': 'Many shop owners and local businesses ask us whether they should have an online store. The honest answer is: it depends. An online store can be the best thing you do for your revenue, or a significant investment that doesn\'t pay off. Here we help you decide.',
    'a.bo.10': 'An online store is especially useful when you have many products and customers need to see the full catalogue to decide. If you have 5 very simple products, a basic contact or order form may be enough without the complexity of a full online store.',
    'a.bo.11': 'When it does NOT make sense (or it\'s not the right time)',
    'a.bo.12': 'You sell services, not products',
    'a.bo.13': 'If you\'re a consultant, doctor, lawyer, designer, consultant or any service professional, you don\'t need an online store — you need a well-made presentation website with a contact form. Selling services requires prior conversation, not a shopping cart.',
    'a.bo.14': 'You don\'t have time to manage it',
    'a.bo.15': 'An online store doesn\'t run itself. You need to add and update products, manage stock, answer customer enquiries, prepare and ship orders, handle returns... If you can\'t dedicate 5 to 10 hours a week to the store, better to wait until you can do it properly.',
    'a.bo.16': 'You\'re just starting out and don\'t know if the product will sell',
    'a.bo.17': 'Creating an online store before validating that the product has demand is risky. Better to sell first through the simplest channels (Instagram, Wallapop, Etsy, local market) to confirm there\'s interest, and then invest in a professional store.',
    'a.bo.18': 'What an online store really costs',
    'a.bo.19': 'The cost of an online store goes far beyond the development price. Here\'s the real breakdown:',
    'a.bo.2': 'When an online store DOES make sense',
    'a.bo.20': '<strong>Development:</strong> €800 - €3,000 for a professional store',
    'a.bo.21': '<strong>Proper hosting:</strong> €15 - €50/month (stores need better servers than presentation websites)',
    'a.bo.22': '<strong>Payment gateway:</strong> Stripe charges 1.4% + €0.25 per transaction (for European cards). On 100 orders of €50 each, that\'s about €95 in fees',
    'a.bo.23': '<strong>Packaging and courier:</strong> variable, but a standard shipment is around €3 - €8 which you may need to absorb or pass on to the customer',
    'a.bo.24': '<strong>Maintenance and updates:</strong> €30 - €80/month if you delegate it',
    'a.bo.25': '<strong>Marketing:</strong> without advertising or SEO, a new store will receive very little traffic in the first months',
    'a.bo.26': 'Do the maths before you start: how many sales do you need per month to recover the investment and cover recurring costs?',
    'a.bo.27': 'Alternatives to your own online store',
    'a.bo.28': 'If it\'s not the right time for your own store, there are alternatives that let you sell online with less initial investment:',
    'a.bo.29': '<strong>Marketplaces (Amazon, Etsy, Wallapop):</strong> you pay commission but get immediate traffic. Good for validating the product',
    'a.bo.3': 'You have physical products with sufficient margin',
    'a.bo.30': '<strong>Instagram Shopping:</strong> for visual products with an already-built active community',
    'a.bo.31': '<strong>WhatsApp Business:</strong> for direct sales and local customers, WhatsApp is surprisingly effective',
    'a.bo.32': 'Once you\'ve validated the product and demand, it\'s time to invest in a well-made online store of your own.',
    'a.bo.33': 'Success factors for an online store',
    'a.bo.34': 'Online stores that work tend to have in common:',
    'a.bo.35': 'A product with real demand and sufficient margin',
    'a.bo.36': 'Quality product photos (the main reason something is bought or not)',
    'a.bo.37': 'Clear and detailed product descriptions',
    'a.bo.38': 'Simple purchase process (too many steps = cart abandonment)',
    'a.bo.39': 'Clear and straightforward returns policy',
    'a.bo.4': 'An online store adds costs: the platform, time to add products, courier service, packaging, returns. If your margin per product is small, ecommerce costs can eat into your profits. As a reference, a net margin of at least 30-40% makes an online store viable.',
    'a.bo.40': 'Product SEO: getting products to appear on Google when someone searches for them',
    'a.bo.41': 'Real customer reviews',
    'a.bo.5': 'Your product can be shipped easily',
    'a.bo.6': 'Small, light products that travel well are ideal for ecommerce. Fragile, very heavy, perishable (fresh food) or complicated-to-install products represent a major logistical challenge that can make the online store unviable without a well-thought-out operation.',
    'a.bo.7': 'People search for your product online',
    'a.bo.8': 'Some products are mostly bought online (clothing, electronics, accessories, niche products) and others are preferably bought in-store (fresh food, services). If your product has online search volume, an online store makes much more sense.',
    'a.bo.9': 'You have a wide and clear catalogue',
