    'a.ft.12': 'How to take good photos with your phone (without being a photographer)',
    'a.ft.13': 'The key to good phone photos isn\'t the camera — it\'s the light. Here are the basic tips:',
    'a.ft.14': 'Optimising photos for the web',
    'a.ft.15': 'Frequently asked questions',
